[1.]
Let $p\in \N^\Z_{\bf f}$ and $r\notin -\text{supp}(p)$. Then we have

\begin{equation*}
X_\beta(r)Y_{\beta}^p=Y^p_\beta X_\beta(r)+\sum_{s\in \text{supp}(p)} \frac{\partial Y_{\beta}^p}{\partial Y_{\beta}(s)}h_{\beta}(r+s)-\frac{\beta(h_\beta)}{2}\sum_{s_1,s_2\in \text{supp}(p)}\frac{\partial^2 Y_{\beta}^p}{\partial Y_{\beta}(s_1)\partial Y_{\beta}(s_2)}Y_{\beta}(s_1+s_2+r).
\end{equation*}

- [2.]
Assume $1\leq i\leq m$, $p_i,\cdots ,p_m\in \N^{\Z}_{\bf f}$ and $r\notin \cup_{j=i}^m-\text{supp}(p_j)$. Then we have

\begin{multline}
X_{\beta_i}(r)Y_{\beta_i}^{p_i}\cdots Y_{\beta_m}^{p_m}=Y_{\beta_i}^{p_i}Y_{\beta_{i+1}}^{p_{i+1}}\cdots Y_{\beta_m}^{p_m}X_{\beta_i}(r)+ Y_{\beta_i}^{p_i} [X_{\beta_i}(r),Y_{\beta_{i+1}}^{p_{i+1}}\cdots Y_{\beta_m}^{p_m} ]
\\ +\sum_{s\in \text{supp}(p_i)} \frac{\partial Y_{\beta_i}^{p_i}}{\partial Y_{\beta_i}(s)}Y_{\beta_{i+1}}^{p_{i+1}}\cdots Y_{\beta_m}^{p_m} h_{\beta_i}(r+s)\\
-\frac{\beta_i(h_{\beta_i})}{2}\sum_{s_1,s_2\in \text{supp}(p_i)}\frac{\partial^2 Y_{\beta_i}^{p_i}}{\partial Y_{\beta_i}(s_1)\partial Y_{\beta_i}(s_2)}Y_{\beta_i}(s_1+s_2+r)Y_{\beta_{i+1}}^{p_{i+1}}\cdots Y_{\beta_m}^{p_m}
\\
-\sum_{s\in \text{supp}(p_i)}\sum_{t=i+1}^m \frac{\partial Y_{\beta_i}^{p_i}}{\partial Y_{\beta_i}(s)} (Y_{\beta_{i+1}}^{p_{i+1}})^*_t\cdots (Y_{\beta_m}^{p_m})^*_t
\end{multline}

where

\[(Y_{\beta_{i+l}}^{p_{i+l}})^*_t=\begin{cases}
Y_{\beta_{i+l}}^{p_{i+l}} & \text{if} \; t\neq i+l\\
\beta_{i+l}(h_{{\beta}_i}) \sum_{s_1\in \text{supp}(p_{i+l})} \frac{\partial Y_{\beta_{i+l}}^{p_{i+l}}}{\partial Y_{\beta_{i+l}}(s_1)}  Y_{\beta_{i+l}}(r+s+s_1)  & \text{if} \; t= i+l
\end{cases}\]

with $1\leq l\leq m-i$.
